#!/usr/bin/env python3\nimport os, random, sys\n\nPHRASES = [\n    "Radiation Storm", "Mutant Horde", "Supply Cache", "Lost Map", "Radio Silence",\n    "Dust Cloud", "Abandoned Shelter", "Scavenger Raid", "Water Purifier", "Solar Flare",\n    "Broken Compass", "Radioactive Waste", "Underground Bunker", "Feral Dogs", "Crumbling Bridge",\n    "Mysterious Signal", "Hidden Vault", "Gas Mask", "Night Vision", "Emergency Rations",\n    "Makeshift Weapon", "Radioactive Zone", "Deserted City", "Wasteland Caravan",\n    "Toxic Fog", "Solar Panel", "Radio Beacon", "Survivor Camp", "Radiation Suit",\n    "Emergency Broadcast"\n]\n\ndef generate_grid(seed=None):\n    if seed is not None:\n        random.seed(seed)\n    chosen = random.sample(PHRASES, 24)\n    # Build 5x5 grid and insert FREE in the center (row 2, col 2)\n    grid = [chosen[i*5:(i+1)*5] for i in range(5)]\n    grid[2][2] = "FREE"\n    return grid\n\ndef format_grid(grid):\n    lines = []\n    for row in grid:\n        # Align cells for pretty printing\n        lines.append(", ".join(f"{cell:>20}" for cell in row))\n    return "\n".join(lines)\n\ndef main():\n    seed = os.getenv("SEED")\n    grid = generate_grid(seed)\n    sys.stdout.write(format_grid(grid) + "\n")\n\nif __name__ == "__main__":\n    main()
